value.query:
query Todos {
  todos {
    ...TodoFields
    __typename
  }
}

fragment TodoFields on Todo {
  id
  title
  done
  __typename
}

query Viewer {
  viewer {
    id
    name
    email
    __typename
  }
}

mutation AddTodo($input: AddTodoInput!) {
  addTodo(input: $input) {
    ...TodoFields
    __typename
  }
}

fragment TodoFields on Todo {
  id
  title
  done
  __typename
}

query Todo($id: ID!) {
  todo(id: $id) {
    ...TodoFields
    status
    owner {
      id
      name
      __typename
    }
    __typename
  }
}

fragment TodoFields on Todo {
  id
  title
  done
  __typename
}

query Search($text: String!) {
  search(text: $text) {
    __typename
    ... on Todo {
      id
      title
      __typename
    }
    ... on User {
      id
      name
      __typename
    }
  }
}
